package com.masaakis.addonfeature.application;
import com.masaakis.addon.application.RequiresAddon;import com.masaakis.security.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class ProductAddonService{private final JdbcClient jdbc;public ProductAddonService(JdbcClient j){jdbc=j;}
 @Transactional(readOnly=true)public Settings settings(StaffPrincipal p){p.require("read");var branches=jdbc.sql("select id,name,active from branch where tenant_id=:t order by created_at").param("t",p.tenantId()).query((rs,n)->new BranchView(rs.getObject(1,UUID.class),rs.getString(2),rs.getBoolean(3),rs.getObject(1,UUID.class).equals(p.branchId()))).list();var brand=jdbc.sql("select brand_primary_color,brand_surface_color,brand_font,brand_layout,hide_powered_by from menu where tenant_id=:t and branch_id=:b order by created_at limit 1").param("t",p.tenantId()).param("b",p.branchId()).query((rs,n)->new Brand(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getBoolean(5))).single();var translations=jdbc.sql("select locale,count(*) from product_translation where tenant_id=:t group by locale order by locale").param("t",p.tenantId()).query((rs,n)->new LocaleProgress(rs.getString(1),rs.getInt(2))).list();long products=jdbc.sql("select count(*) from product p join menu_category c on c.id=p.category_id join menu m on m.id=c.menu_id where p.tenant_id=:t and m.branch_id=:b and p.archived=false").param("t",p.tenantId()).param("b",p.branchId()).query(Long.class).single();return new Settings(branches,brand,translations,(int)products);}
 @RequiresAddon("MULTI_BRANCH")@Transactional public UUID createBranch(StaffPrincipal p,String name){p.require("tenant/manage");long count=jdbc.sql("select count(*) from branch where tenant_id=:t and active=true").param("t",p.tenantId()).query(Long.class).single();if(count>=5)throw new AppException(HttpStatus.CONFLICT,"BRANCH_LIMIT","Bu planda en fazla 5 etkin şube olabilir.");UUID branch=UUID.randomUUID(),menu=UUID.randomUUID();String slug="menu-"+UUID.randomUUID().toString().substring(0,8);jdbc.sql("insert into branch(id,tenant_id,name)values(:id,:t,:n)").param("id",branch).param("t",p.tenantId()).param("n",name.trim()).update();jdbc.sql("insert into menu(id,tenant_id,branch_id,slug,name,locale,published)values(:id,:t,:b,:s,:n,'tr',false)").param("id",menu).param("t",p.tenantId()).param("b",branch).param("s",slug).param("n",name.trim()).update();return branch;}
 @Transactional public void switchBranch(StaffPrincipal p,UUID branch){p.require("tenant/manage");long n=jdbc.sql("select count(*) from branch where id=:b and tenant_id=:t and active=true").param("b",branch).param("t",p.tenantId()).query(Long.class).single();if(n==0)throw new AppException(HttpStatus.NOT_FOUND,"BRANCH_NOT_FOUND","Şube bulunamadı.");jdbc.sql("update staff_session set active_branch_id=:b where id=:s and user_id=:u").param("b",branch).param("s",p.sessionId()).param("u",p.userId()).update();}
 @RequiresAddon("BRANDING")@Transactional public void branding(StaffPrincipal p,Brand b){p.require("catalog/write");if(!b.primaryColor.matches("#[0-9A-Fa-f]{6}")||!b.surfaceColor.matches("#[0-9A-Fa-f]{6}")||!Set.of("SYSTEM","SERIF","ROUNDED").contains(b.font)||!Set.of("CARDS","COMPACT").contains(b.layout))throw new AppException(HttpStatus.BAD_REQUEST,"BRANDING_INVALID","Marka seçenekleri geçersiz.");jdbc.sql("update menu set brand_primary_color=:p,brand_surface_color=:s,brand_font=:f,brand_layout=:l,hide_powered_by=:h,updated_at=now() where tenant_id=:t and branch_id=:b").param("p",b.primaryColor).param("s",b.surfaceColor).param("f",b.font).param("l",b.layout).param("h",b.hidePoweredBy).param("t",p.tenantId()).param("b",p.branchId()).update();}
 @RequiresAddon("MULTILINGUAL")@Transactional public void translate(StaffPrincipal p,String locale,UUID menuId,String menuName,String menuDescription,List<CategoryText>categories,List<ProductText>products){p.require("catalog/write");if(!locale.matches("[a-z]{2}(?:-[A-Z]{2})?"))throw new AppException(HttpStatus.BAD_REQUEST,"LOCALE_INVALID","Dil kodu geçersiz.");long owned=jdbc.sql("select count(*) from menu where id=:m and tenant_id=:t and branch_id=:b").param("m",menuId).param("t",p.tenantId()).param("b",p.branchId()).query(Long.class).single();if(owned==0)throw new AppException(HttpStatus.NOT_FOUND,"MENU_NOT_FOUND","Menü bulunamadı.");jdbc.sql("insert into menu_translation(menu_id,tenant_id,locale,name,description)values(:m,:t,:l,:n,:d) on conflict(menu_id,locale)do update set name=excluded.name,description=excluded.description").param("m",menuId).param("t",p.tenantId()).param("l",locale).param("n",menuName.trim()).param("d",clean(menuDescription,500)).update();for(var x:categories)jdbc.sql("insert into category_translation(category_id,tenant_id,locale,name)select :id,:t,:l,:n where exists(select 1 from menu_category where id=:id and tenant_id=:t and menu_id=:m) on conflict(category_id,locale)do update set name=excluded.name").param("id",x.id).param("t",p.tenantId()).param("l",locale).param("n",x.name.trim()).param("m",menuId).update();for(var x:products)jdbc.sql("insert into product_translation(product_id,tenant_id,locale,name,description,allergen_info)select :id,:t,:l,:n,:d,:a where exists(select 1 from product p join menu_category c on c.id=p.category_id where p.id=:id and p.tenant_id=:t and c.menu_id=:m) on conflict(product_id,locale)do update set name=excluded.name,description=excluded.description,allergen_info=excluded.allergen_info").param("id",x.id).param("t",p.tenantId()).param("l",locale).param("n",x.name.trim()).param("d",clean(x.description,1000)).param("a",clean(x.allergens,500)).param("m",menuId).update();}
 @RequiresAddon("ADVANCED_REPORTS")@Transactional(readOnly=true)public Report report(StaffPrincipal p,LocalDate from,LocalDate to){p.require("read");if(from==null||to==null||to.isBefore(from)||from.plusDays(90).isBefore(to))throw new AppException(HttpStatus.BAD_REQUEST,"REPORT_RANGE","Rapor aralığı en fazla 90 gün olmalı.");OffsetDateTime start=from.atStartOfDay().atOffset(ZoneOffset.UTC),end=to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC);var states=jdbc.sql("select state,count(*),coalesce(sum(estimated_total),0) from customer_order where tenant_id=:t and branch_id=:b and submitted_at>=:f and submitted_at<:e group by state order by state").param("t",p.tenantId()).param("b",p.branchId()).param("f",start).param("e",end).query((rs,n)->new StateMetric(rs.getString(1),rs.getLong(2),rs.getBigDecimal(3))).list();var top=jdbc.sql("select oi.product_name_snapshot,sum(oi.quantity) quantity from order_item oi join customer_order o on o.id=oi.order_id where oi.tenant_id=:t and o.branch_id=:b and o.submitted_at>=:f and o.submitted_at<:e group by oi.product_name_snapshot order by quantity desc limit 10").param("t",p.tenantId()).param("b",p.branchId()).param("f",start).param("e",end).query((rs,n)->new ProductMetric(rs.getString(1),rs.getLong(2))).list();return new Report(from,to,"Tahmini sipariş değeri ödeme, tahsilat veya kesin ciro değildir.",states,top);}
 private static String clean(String s,int max){if(s==null||s.isBlank())return null;return s.trim().substring(0,Math.min(max,s.trim().length()));}
 public record BranchView(UUID id,String name,boolean active,boolean current){}public record Brand(String primaryColor,String surfaceColor,String font,String layout,boolean hidePoweredBy){}public record LocaleProgress(String locale,int translatedProducts){}public record Settings(List<BranchView>branches,Brand branding,List<LocaleProgress>translations,int totalProducts){}public record CategoryText(UUID id,String name){}public record ProductText(UUID id,String name,String description,String allergens){}public record StateMetric(String state,long orderCount,BigDecimal estimatedOrderValue){}public record ProductMetric(String productName,long quantity){}public record Report(LocalDate from,LocalDate to,String disclaimer,List<StateMetric>states,List<ProductMetric>topProducts){}
}
